using System;using System.Collections.Generic;using WildsEngine.Discoveries.Abstractions.Clusters;using WildsEngine.Discoveries.Abstractions.Narratives;using WildsEngine.Discoveries.Clusters;using WildsEngine.Discoveries.Narratives;using WildsEngine.Discoveries.Policies;using WildsEngine.Discoveries.Surface;using Xunit;
namespace WildsEngine.Core.Tests.Entities.Certifications { public sealed class DiscoveryNarrativeCompositionCertificationTests { [Fact]public void SuppliedRelationshipComposesWithoutAveragingSources(){var x=Fixture();var rel=new DiscoveryNarrativeRelationshipDefinition(Guid.NewGuid(),"rel",x.A,x.B,"SimilarPreference");var p=new DiscoveryNarrativeProfile(Guid.NewGuid(),"pizza-narrative","1","pizza-party",new RelationshipKeyNarrativeCompositionPolicy("SimilarPreference"),new RecognitionCentroidDistanceNarrativeMetric(),new List<IDiscoveryNarrativeRelationshipDefinition>{rel});var nr=x.D.Narratives.Register(p);var result=x.D.Narratives.Compose(x.Pop,nr.Id);Assert.Single(result.Groups);Assert.Equal(2,result.Groups[0].Members.Count);Assert.Same(x.Pop,result.Population);Assert.Equal(nr.Id,result.Registration.Id);}[Fact]public void MissingRelationshipPreservesSeparateNarratives(){var x=Fixture();var p=new DiscoveryNarrativeProfile(Guid.NewGuid(),"pizza-narrative","1","pizza-party",new RelationshipKeyNarrativeCompositionPolicy("SimilarPreference"),new RecognitionCentroidDistanceNarrativeMetric(),new List<IDiscoveryNarrativeRelationshipDefinition>());var nr=x.D.Narratives.Register(p);var result=x.D.Narratives.Compose(x.Pop,nr.Id);Assert.Equal(2,result.Groups.Count);}[Fact]public void ScopeMismatchFails(){var x=Fixture();var p=new DiscoveryNarrativeProfile(Guid.NewGuid(),"other","1","other-scope",new RelationshipKeyNarrativeCompositionPolicy("X"),new RecognitionCentroidDistanceNarrativeMetric(),new List<IDiscoveryNarrativeRelationshipDefinition>());var nr=x.D.Narratives.Register(p);Assert.Throws<InvalidOperationException>(()=>x.D.Narratives.Compose(x.Pop,nr.Id));}private static F Fixture(){var d=new WildsDiscoveries();var id=Guid.NewGuid();const string a="PepperoniOliveMushroomOnion",b="PepperoniSausageJalapenoOnion";var maps=new List<IDiscoveryClusterMapping>{Map(id,"a",a,0),Map(id,"b",b,10)};var gr=d.Geometry.Register(new DiscoveryGeometryProfile(id,"pizza","1","pizza-party",maps,new MinimumClusterPersistencePolicy("p",1,0,0),new BoundaryVarianceClusterStabilityMetric(),new PersistentClusterRecognitionPolicy()));var f=new H2TestFixture();var ra=d.Geometry.Observe(f.Eval(DateTimeOffset.UtcNow,("x",.1),("y",0)),a).Recognition;var rb=d.Geometry.Observe(f.Eval(DateTimeOffset.UtcNow,("x",9.9),("y",0)),b).Recognition;var pop=d.Narratives.CreatePopulation(gr.Id,new List<IDiscoveryClusterRecognitionResult>{ra,rb});return new F(d,pop,a,b);}private static IDiscoveryClusterMapping Map(Guid id,string slug,string key,double x)=>new DiscoveryClusterMapping(Guid.NewGuid(),slug,id,"pizza","1",key,"hypersphere",new Dictionary<string,double>{{"x",x},{"y",0}},1);private sealed class F{public F(WildsDiscoveries d,IDiscoveryRecognizedGeometryPopulation p,string a,string b){D=d;Pop=p;A=a;B=b;}public WildsDiscoveries D{get;}public IDiscoveryRecognizedGeometryPopulation Pop{get;}public string A{get;}public string B{get;}} } }
